@Component("encounter-handler")
@ProcessingGroup("encounter-processing-group")
public class EncounterEventHandler {
	
	// core constructor
	EncounterEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateEncounterEvent
     */
    @EventHandler
    public void handle( CreateEncounterEvent event) {
        entityManager.persist(new Encounter(event.getEncounterId(), event.getEncounterNumber(), event.getStartDateTime(), event.getEndDateTime(), event.getPatient(), event.getClinician(), event.getFacility(), event.getAppointment(), event.getDiagnoses(), event.getProcedures(), event.getObservations(), event.getOrders(), event.getAdmission(), event.getDischarge(), event.getStatus(), event.getEncounterType()));
    }

    /*
     * @param	event UpdateEncounterEvent
     */
    @EventHandler
    public Encounter handle( UpdateEncounterEvent event) {
    	entityManager.merge(new Encounter(event.getEncounterId(), event.getEncounterNumber(), event.getStartDateTime(), event.getEndDateTime(), event.getPatient(), event.getClinician(), event.getFacility(), event.getAppointment(), event.getDiagnoses(), event.getProcedures(), event.getObservations(), event.getOrders(), event.getAdmission(), event.getDischarge(), event.getStatus(), event.getEncounterType()));
    }
    
    /*
     * @param	event DeleteEncounterEvent
     */
    @EventHandler
    public void on( DeleteEncounterEvent event) {
    	Encounter entity = new Encounter();
   
    	// ------------------------------------------
    	// apply the EncounterId
    	// ------------------------------------------
    	entity.setEncounterId( event.getEncounterId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final EncounterRepository encounterEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(EncounterEventHandler.class.getName());

}
